import{_ as n,o as e,c as t,a2 as i}from"./chunks/framework.DBU8LMUS.js";const k=JSON.parse('{"title":"Tentang Aplikasi","description":"","frontmatter":{"title":"Tentang Aplikasi","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/index.md","filePath":"latest/index.md","lastUpdated":1786334463000}'),r={name:"latest/index.md"};function l(o,a,s,u,d,g){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="tentang-aplikasi" tabindex="-1">Tentang Aplikasi <a class="header-anchor" href="#tentang-aplikasi" aria-label="Permalink to &quot;Tentang Aplikasi&quot;">​</a></h1><h2 id="deskripsi-umum" tabindex="-1">Deskripsi Umum <a class="header-anchor" href="#deskripsi-umum" aria-label="Permalink to &quot;Deskripsi Umum&quot;">​</a></h2><p><strong>ILUNI FT ELEKTRO UNPAK</strong> adalah platform database alumni sekaligus wadah jejaring (networking) untuk <strong>Ikatan Alumni Fakultas Teknik Program Studi Teknik Elektro Universitas Pakuan Bogor</strong>. Aplikasi ini mempertemukan para alumni lintas angkatan untuk:</p><ul><li>Saling terhubung melalui <strong>direktori alumni</strong> yang dapat dicari.</li><li>Membagikan <strong>lowongan kerja</strong> dan memanfaatkan <strong>sistem referral</strong>.</li><li>Mengikuti <strong>program mentoring</strong> antara alumni senior dan junior.</li><li>Berdiskusi dalam <strong>komunitas &amp; grup</strong> beserta forum diskusinya.</li><li>Berinteraksi melalui <strong>pengumuman</strong>, <strong>polling</strong>, dan <strong>galeri kegiatan</strong>.</li><li>Berkontribusi dan bersaing sehat di <strong>peringkat kontribusi</strong>.</li></ul><h2 id="fitur-utama" tabindex="-1">Fitur Utama <a class="header-anchor" href="#fitur-utama" aria-label="Permalink to &quot;Fitur Utama&quot;">​</a></h2><h3 id="akun-dan-profil" tabindex="-1">Akun dan Profil <a class="header-anchor" href="#akun-dan-profil" aria-label="Permalink to &quot;Akun dan Profil&quot;">​</a></h3><ul><li>Pendaftaran dengan email dan kata sandi, dilanjutkan verifikasi email.</li><li>Profil alumni lengkap: data diri, pekerjaan, perusahaan, keahlian (skills), dan angkatan.</li><li>Unggah <strong>foto profil</strong> dan <strong>resume (PDF maksimal 2 MB)</strong>.</li><li>Toggle <strong>Open to Work</strong> untuk menampilkan ketersediaan menerima tawaran kerja.</li></ul><h3 id="jejaring-alumni" tabindex="-1">Jejaring Alumni <a class="header-anchor" href="#jejaring-alumni" aria-label="Permalink to &quot;Jejaring Alumni&quot;">​</a></h3><ul><li><strong>Direktori alumni</strong> dengan pencarian dan filter (nama, angkatan, pekerjaan, perusahaan, keahlian).</li><li><strong>Komunitas &amp; grup</strong> berdasarkan angkatan atau minat, dilengkapi <strong>forum diskusi</strong> berisi thread dan balasan.</li><li><strong>Sistem referral</strong> untuk meminta rekomendasi ke alumni di perusahaan tujuan.</li></ul><h3 id="peluang-dan-pengembangan" tabindex="-1">Peluang dan Pengembangan <a class="header-anchor" href="#peluang-dan-pengembangan" aria-label="Permalink to &quot;Peluang dan Pengembangan&quot;">​</a></h3><ul><li><strong>Lowongan kerja</strong> yang diunggah alumni terverifikasi, dapat disaring berdasarkan keahlian.</li><li><strong>Program mentoring</strong> dengan alur permintaan <code>pending → diterima → selesai</code>.</li></ul><h3 id="interaksi-komunitas" tabindex="-1">Interaksi Komunitas <a class="header-anchor" href="#interaksi-komunitas" aria-label="Permalink to &quot;Interaksi Komunitas&quot;">​</a></h3><ul><li><strong>Pengumuman</strong> dalam kategori pencapaian, lowongan, event, dan umum.</li><li><strong>Polling</strong> dengan aturan satu suara per pengguna.</li><li><strong>Galeri kegiatan</strong> untuk berbagi dokumentasi acara.</li><li><strong>Peringkat kontribusi</strong> berdasarkan skor kontribusi anggota.</li></ul><h3 id="moderasi-dan-pengelolaan" tabindex="-1">Moderasi dan Pengelolaan <a class="header-anchor" href="#moderasi-dan-pengelolaan" aria-label="Permalink to &quot;Moderasi dan Pengelolaan&quot;">​</a></h3><ul><li><strong>Pelaporan konten</strong> untuk menjaga kenyamanan komunitas.</li><li><strong>Panel admin</strong> untuk pengelolaan pengguna, data alumni, moderasi, serta impor/ekspor data CSV.</li></ul><h2 id="teknologi-yang-digunakan" tabindex="-1">Teknologi yang Digunakan <a class="header-anchor" href="#teknologi-yang-digunakan" aria-label="Permalink to &quot;Teknologi yang Digunakan&quot;">​</a></h2><ul><li><strong>Framework</strong>: Next.js (App Router)</li><li><strong>Database &amp; Autentikasi</strong>: Supabase (PostgreSQL dengan Row Level Security)</li><li><strong>Gaya</strong>: Tailwind CSS</li></ul><h2 id="cara-mengakses" tabindex="-1">Cara Mengakses <a class="header-anchor" href="#cara-mengakses" aria-label="Permalink to &quot;Cara Mengakses&quot;">​</a></h2><h3 id="melalui-peramban" tabindex="-1">Melalui Peramban <a class="header-anchor" href="#melalui-peramban" aria-label="Permalink to &quot;Melalui Peramban&quot;">​</a></h3><p>Aplikasi dapat diakses melalui alamat berikut:</p><ul><li><strong>Produksi (Vercel)</strong>: <code>https://ilunifteunpak.vercel.app</code></li><li><strong>Lingkungan pengembangan lokal</strong>: <code>http://localhost:3000</code> (setelah menjalankan <code>bun dev</code>)</li></ul><h3 id="dokumen-panduan-ini" tabindex="-1">Dokumen Panduan Ini <a class="header-anchor" href="#dokumen-panduan-ini" aria-label="Permalink to &quot;Dokumen Panduan Ini&quot;">​</a></h3><p>Panduan ini disusun per modul. Gunakan menu navigasi di sisi kiri untuk berpindah antarmodul, atau tombol <strong>Cari</strong> di bagian atas untuk mencari topik tertentu.</p><div class="tip custom-block"><p class="custom-block-title">Unduhan PDF</p><p>Versi lengkap panduan ini dapat diunduh dalam satu berkas PDF melalui tautan berikut:</p><p><a href="/webapps/webapps/pdfs/manual-latest.pdf">Unduh Manual Lengkap (PDF)</a></p></div><h2 id="peran-pengguna" tabindex="-1">Peran Pengguna <a class="header-anchor" href="#peran-pengguna" aria-label="Permalink to &quot;Peran Pengguna&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Peran</th><th>Deskripsi</th></tr></thead><tbody><tr><td><strong>Alumni (terdaftar)</strong></td><td>Pengguna yang sudah mendaftar dan memverifikasi email. Dapat mengisi profil, bergabung dengan grup, membuat polling, dan lain-lain.</td></tr><tr><td><strong>Alumni terverifikasi</strong></td><td>Alumni yang profilnya diverifikasi oleh admin. Memiliki hak membuat lowongan dan pengumuman.</td></tr><tr><td><strong>Admin</strong></td><td>Pengelola dengan kemampuan tertentu (misalnya moderasi konten, kelola data alumni) sesuai yang diberikan super admin.</td></tr><tr><td><strong>Super Admin</strong></td><td>Pengelola penuh. Dapat mengelola pengguna, menetapkan admin, dan mengakses seluruh modul moderasi.</td></tr></tbody></table><h2 id="struktur-panduan" tabindex="-1">Struktur Panduan <a class="header-anchor" href="#struktur-panduan" aria-label="Permalink to &quot;Struktur Panduan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Modul</th><th>Halaman</th></tr></thead><tbody><tr><td>Panduan Pengguna</td><td>Memulai, Profil, Direktori, Lowongan, Mentoring, Referral, Grup, Pengumuman, Polling, Galeri, Peringkat, Melaporkan Konten</td></tr><tr><td>Panduan Admin</td><td>Kelola Pengguna, Kelola Alumni, Moderasi Konten, Impor &amp; Ekspor CSV</td></tr><tr><td>Lainnya</td><td>Pemecahan Masalah</td></tr></tbody></table><p>Lanjutkan ke halaman <a href="/webapps/latest/mulai">Memulai</a> untuk panduan pendaftaran dan masuk.</p>',29)])])}const p=n(r,[["render",l]]);export{k as __pageData,p as default};
